insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-14','verbeterd','Mobiel','Overzichtelijker startscherm in de app',
   'De knoppen staan nu met drie naast elkaar, zodat je niet meer hoeft te scrollen. Bovenaan zie je meteen je planning voor vandaag en wat er van je verwacht wordt, zoals een weekstaat die je nog moet indienen. De groene balk loopt door tot bovenaan het scherm, net als in een gewone app.'),
  ('2026-09-14','nieuw','Uren','Uren fiatteren op je telefoon',
   'Teamleiders en projectleiders kunnen uren nu vanaf hun telefoon goedkeuren, per project gebundeld. De teamleider kan een regel eerst nog bijstellen — uren, bewakingscode of opmerking — voordat hij akkoord geeft; de medewerker krijgt daar automatisch bericht van.'),
  ('2026-09-14','verbeterd','Uren','De teamleider kijkt eerst naar de uren',
   'Uren gaan voortaan eerst langs de teamleider en pas daarna naar de projectleider. Zo worden ze niet goedgekeurd voordat de teamleider ze heeft kunnen nakijken. Is de teamleider er niet, bijvoorbeeld door verlof, dan kan de projectleider er alsnog overheen na een bevestiging — het werk blijft dus nooit hangen.');
